-- CREATE definition generated by Microsoft DacFx from a data-free DACPAC.
-- Reference only; do not execute directly on a school database.

CREATE   PROCEDURE dbo.GetCampuses
@UserId INT
AS
BEGIN
    SET NOCOUNT ON;
    EXECUTE dbo.RequireAuthenticatedUser @UserId;
    SELECT DisplayOrder, CampusId,
             CampusCode,
             CampusName,
             CampusType,
             AddressLine,
             City,
             ContactNumber,
             Email
    FROM     dbo.Campuses
    ORDER BY DisplayOrder, CampusId;
END
